<?php
require_once __DIR__.'/../../includes/staff/operations.php';require_login();$pdo=staff_db();$staff=current_staff();$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$start=$month.'-01';$end=date('Y-m-d',strtotime($start.' +1 month'));$events=[];
$q=$pdo->prepare("SELECT id,title,due_date FROM tasks WHERE assigned_to=? AND due_date>=? AND due_date<? AND status NOT IN('cancelled')");$q->execute([$staff['id'],$start,$end]);foreach($q->fetchAll() as $r)$events[date('Y-m-d',strtotime($r['due_date']))][]=['label'=>'Task: '.$r['title'],'url'=>'staff/pages/tasks.php'];
$q=$pdo->prepare("SELECT f.id,f.customer_id,f.follow_up_at,f.reason,c.name customer_name FROM follow_ups f JOIN customers c ON c.id=f.customer_id WHERE f.assigned_to=? AND f.follow_up_at>=? AND f.follow_up_at<? AND f.status='pending'");$q->execute([$staff['id'],$start,$end]);foreach($q->fetchAll() as $r)$events[date('Y-m-d',strtotime($r['follow_up_at']))][]=['label'=>'Follow-up: '.$r['customer_name'].' · '.$r['reason'],'url'=>'staff/pages/customer-view.php?id='.$r['customer_id']];
$q=$pdo->prepare("SELECT p.id,p.project_code,p.name,p.target_date FROM projects p WHERE p.assigned_manager=? AND p.target_date>=? AND p.target_date<? AND p.status NOT IN('completed','cancelled')");$q->execute([$staff['id'],$start,$end]);foreach($q->fetchAll() as $r)$events[$r['target_date']][]=['label'=>'Target: '.$r['project_code'].' · '.$r['name'],'url'=>'staff/pages/project-view.php?id='.$r['id']];
$firstDow=(int)date('N',strtotime($start));$days=(int)date('t',strtotime($start));$prev=date('Y-m',strtotime($start.' -1 month'));$next=date('Y-m',strtotime($start.' +1 month'));$pageTitle='Calendar';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Schedule</p><h1><?= h(date('F Y',strtotime($start))) ?></h1><p class="muted">Your tasks, follow-ups and project target dates.</p></div><div class="actions"><a class="btn" href="?month=<?= h($prev) ?>">← Previous</a><a class="btn" href="?month=<?= h(date('Y-m')) ?>">Today</a><a class="btn" href="?month=<?= h($next) ?>">Next →</a></div></div><section class="staff-panel"><div class="calendar-grid"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $d):?><strong><?= $d ?></strong><?php endforeach;?><?php for($i=1;$i<$firstDow;$i++):?><div class="calendar-day"></div><?php endfor;?><?php for($day=1;$day<=$days;$day++):$date=$month.'-'.str_pad((string)$day,2,'0',STR_PAD_LEFT);?><div class="calendar-day"><strong><?= $day ?></strong><?php foreach($events[$date]??[] as $e):?><a class="calendar-event" href="<?= h(ideare_root_url($e['url'])) ?>"><?= h($e['label']) ?></a><?php endforeach;?></div><?php endfor;?></div></section></main><?php require __DIR__.'/../../includes/staff/footer.php'; ?>
